locals {
 ecs_assume=jsonencode({
 Version="2012-10-17"
 Statement=[{
 Effect="Allow"
 Action="sts:AssumeRole"
 Principal={Service="ecs-tasks.amazonaws.com"}
 Condition={
 StringEquals={"aws:SourceAccount"=data.aws_caller_identity.current.account_id}
 ArnLike={
 "aws:SourceArn"=[
 "arn:aws:ecs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:cluster/${local.name_prefix}-cluster",
 "arn:aws:ecs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:task-definition/${local.name_prefix}-api:*",
]
}
}
}]
})
}
resource "aws_iam_role" "ecs_task_execution" {
 name="${local.name_prefix}-ecs-exec"
 assume_role_policy=local.ecs_assume
 tags={Name="${local.name_prefix}-ecs-exec"}
}
resource "aws_iam_role_policy_attachment" "ecs_task_execution_managed" {
 role=aws_iam_role.ecs_task_execution.name
 policy_arn="arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}
resource "aws_iam_role_policy" "ecs_task_execution_secrets" {
 name="${local.name_prefix}-ecs-exec-secrets"
 role=aws_iam_role.ecs_task_execution.id
 policy=jsonencode({
 Version="2012-10-17"
 Statement=[{
 Sid="ReadAppAndRdsSecrets"
 Effect="Allow"
 Action=["secretsmanager:GetSecretValue","secretsmanager:DescribeSecret"]
 Resource=[
 "arn:aws:secretsmanager:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:secret:${local.name_prefix}/*",
 var.master_user_secret_arn,
 "${var.master_user_secret_arn}*",
]
}]
})
}
resource "aws_iam_role" "ecs_task" {
 name="${local.name_prefix}-ecs-task"
 assume_role_policy=local.ecs_assume
 tags={Name="${local.name_prefix}-ecs-task"}
}
resource "aws_iam_role_policy" "ecs_task" {
 name="${local.name_prefix}-ecs-task"
 role=aws_iam_role.ecs_task.id
 policy=jsonencode({
 Version="2012-10-17"
 Statement=[
 {
 Sid="ReadAssetsBucket"
 Effect="Allow"
 Action=["s3:GetObject","s3:ListBucket"]
 Resource=[var.assets_bucket_arn,"${var.assets_bucket_arn}/*"]
},
 {
 Sid="WriteApplicationLogs"
 Effect="Allow"
